{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "街明かり華やか",
        "エーテル麻酔の冷たさ",
        "眠れない午前二時",
        "全てが急速に変わる",
        "オイル切れのライター",
        "焼けつくような胃の中",
        "全てがそう嘘なら",
        "本当によかったのにね"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "君の首を締める夢を見た",
        "光の溢れる昼下がり",
        "君の細い喉が跳ねるのを",
        "泣き出しそうな眼で見ていた"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたいと思う",
        "真っ青な光包まれて奇麗",
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "すべてが許されるような気がして"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "ベランダの向こう側",
        "階段を昇ってゆく音",
        "陰り出した空が",
        "窓ガラスに 部屋に落ちる",
        "拡散する夕暮れ",
        "泣き腫らしたような陽の赤",
        "融けるように少しずつ",
        "少しずつ死んでゆく世界",
        "君の首を締める夢を見た",
        "春風に揺れるカーテン",
        "乾いて切れた唇から",
        "零れる言葉は泡のよう"
      ]
    },
    {
      "section": "C2",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたいと思う",
        "真っ青な光包まれて奇麗",
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "すべてが許されるような気がして"
      ]
    },
    {
      "section": "V3",
      "lyrics": [
        "時計の秒針や",
        "テレビの司会者や",
        "そこにいるけど",
        "見えない誰かの",
        "笑い声",
        "飽和して反響する",
        "アレグロ･アジテート",
        "耳鳴りが消えない止まない",
        "アレグロ･アジテート",
        "耳鳴りが消えない止まない"
      ]
    },
    {
      "section": "B2",
      "lyrics": [
        "誰もみんな消えてく夢を見た",
        "真夜中の部屋の広さと静寂が",
        "胸につっかえて",
        "上手に息ができなくなる"
      ]
    },
    {
      "section": "C3",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "きっと眠るように消えていけるんだ",
        "僕のいない朝は",
        "今よりずっと素晴らしくて",
        "全ての歯車が噛み合った",
        "きっとそんな世界だ"
      ]
    }
  ],
  "section": "B2",
  "phrases": [
    {
      "id": "B2-01",
      "ja": "誰もみんな消えてく夢を見た",
      "budget": {
        "min": 15,
        "max": 15
      },
      "pattern": null
    },
    {
      "id": "B2-02",
      "ja": "真夜中の部屋の広さと静寂が",
      "budget": {
        "min": 17,
        "max": 17
      },
      "pattern": null
    },
    {
      "id": "B2-03",
      "ja": "胸につっかえて",
      "budget": {
        "min": 7,
        "max": 7
      },
      "pattern": null
    },
    {
      "id": "B2-04",
      "ja": "上手に息ができなくなる",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": null
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B2-01",
          "zh": "我梦见 所有人都 一个一个 消失不见"
        },
        {
          "id": "B2-02",
          "zh": "午夜的房间 宽得发慌 静到能听见血在流"
        },
        {
          "id": "B2-03",
          "zh": "堵在胸口 出不去"
        },
        {
          "id": "B2-04",
          "zh": "连好好吸一口气 也都做不到"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B2-01",
          "zh": "梦见所有人 全都消失不见"
        },
        {
          "id": "B2-02",
          "zh": "深夜的房间 空旷又寂静 压得人喘不过气"
        },
        {
          "id": "B2-03",
          "zh": "堵在胸口 散不去"
        },
        {
          "id": "B2-04",
          "zh": "连呼吸都变得好困难"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B2-01",
          "zh": "梦见所有人 都消失不见"
        },
        {
          "id": "B2-02",
          "zh": "深夜房间的空旷 寂静压下来"
        },
        {
          "id": "B2-03",
          "zh": "堵在胸口 散不开"
        },
        {
          "id": "B2-04",
          "zh": "连呼吸都变得好难"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B2-01",
          "zh": "我梦见这世界上所有人都消失无踪"
        },
        {
          "id": "B2-02",
          "zh": "深夜房间的空旷与那无边无际的寂静重"
        },
        {
          "id": "B2-03",
          "zh": "堵在了胸口难通"
        },
        {
          "id": "B2-04",
          "zh": "呼吸它变得不再顺畅而从容"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B2-01",
          "zh": "我梦见所有人都消失了"
        },
        {
          "id": "B2-02",
          "zh": "午夜房间的宽广与寂静"
        },
        {
          "id": "B2-03",
          "zh": "堵在胸口"
        },
        {
          "id": "B2-04",
          "zh": "让我无法好好呼吸"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "B2-01",
          "zh": "梦见这世上的人 一个一个 全都消失"
        },
        {
          "id": "B2-02",
          "zh": "深夜的房间 大得空旷 静得能听见心跳声"
        },
        {
          "id": "B2-03",
          "zh": "堵在胸口 咽不下"
        },
        {
          "id": "B2-04",
          "zh": "连一次完整的呼吸 都做不到"
        }
      ]
    }
  ]
}

